package bits.ui;
import bits.dao.CategoryDAO;import bits.dao.ComponentDAO;import bits.model.Category;import bits.model.Component;import bits.model.User;import javax.swing.*;import javax.swing.table.DefaultTableModel;import java.awt.*;import java.sql.SQLException;import java.util.*;import java.util.List;
public class DashboardFrame extends JFrame {
 private final User user;private final ComponentDAO dao=new ComponentDAO();private final CategoryDAO categoriesDao=new CategoryDAO();private final JTextField search=new JTextField(20);private final DefaultTableModel model=new DefaultTableModel(new Object[]{"ID","Component","Value / rating","Category","Quantity","Location","Notes"},0){public boolean isCellEditable(int r,int c){return false;}};private final JTable table=new JTable(model);
 public DashboardFrame(User user){super("BITS | Inventory — "+user.getName());this.user=user;setDefaultCloseOperation(EXIT_ON_CLOSE);setSize(1280,760);setMinimumSize(new Dimension(1000,620));setLocationRelativeTo(null);JPanel root=new JPanel(new BorderLayout(0,10));root.setBackground(Theme.BG);root.setBorder(BorderFactory.createEmptyBorder(14,16,10,16));setContentPane(root);JPanel top=new JPanel(new FlowLayout(FlowLayout.LEFT,8,8));top.setBackground(Theme.SURFACE);top.setBorder(BorderFactory.createCompoundBorder(new javax.swing.border.LineBorder(new Color(42,58,86),1,true),BorderFactory.createEmptyBorder(5,8,5,8)));top.add(new JLabel("Search"));top.add(search);JButton find=new JButton("Search"),refresh=new JButton("Refresh"),add=new JButton("Add component"),edit=new JButton("Edit"),plus=new JButton("Stock +"),minus=new JButton("Stock -"),del=new JButton("Delete"),cat=new JButton("Add category"),logout=new JButton("Logout");for(JButton b:List.of(find,refresh,add,edit,plus,minus,del,cat,logout))top.add(b);root.add(top,BorderLayout.NORTH);table.setSelectionMode(ListSelectionModel.SINGLE_SELECTION);table.setAutoCreateRowSorter(true);root.add(new JScrollPane(table),BorderLayout.CENTER);JLabel foot=new JLabel("Signed in as "+user.getEmail()+"   |   BITS — Electronics component inventory");foot.setBorder(BorderFactory.createEmptyBorder(8,10,8,10));foot.setForeground(Theme.MUTED);root.add(foot,BorderLayout.SOUTH);Theme.styleWindow(this);add.setBackground(Theme.ACCENT);add.setForeground(Color.WHITE);plus.setBackground(new Color(23,91,78));minus.setBackground(new Color(86,65,30));del.setBackground(new Color(90,38,50));find.addActionListener(e->load());refresh.addActionListener(e->{search.setText("");load();});search.addActionListener(e->load());add.addActionListener(e->editComponent(null));edit.addActionListener(e->{Component c=selected();if(c!=null)editComponent(c);});plus.addActionListener(e->stock(1));minus.addActionListener(e->stock(-1));del.addActionListener(e->delete());cat.addActionListener(e->addCategory());logout.addActionListener(e->{dispose();new LoginFrame().setVisible(true);});load();}
 private void load(){try{model.setRowCount(0);for(Component c:dao.list(user.getId(),search.getText()))model.addRow(new Object[]{c.getId(),c.getName(),c.getValue(),c.getCategory(),c.getQuantity(),c.getLocation(),c.getNotes()});}catch(SQLException ex){LoginFrame.dbError(ex);}}
 private int selectedId(){int row=table.getSelectedRow();return row<0?-1:Integer.parseInt(model.getValueAt(table.convertRowIndexToModel(row),0).toString());}
 private Component selected(){int id=selectedId();if(id<0){JOptionPane.showMessageDialog(this,"Select a component first.");return null;}try{for(Component c:dao.list(user.getId(),""))if(c.getId()==id)return c;}catch(SQLException ex){LoginFrame.dbError(ex);}return null;}
 private void editComponent(Component existing){try{ComponentDialog d=new ComponentDialog(this,categoriesDao.list(user.getId()),existing);d.setVisible(true);if(d.saved()){dao.save(user.getId(),existing==null?0:existing.getId(),d.categoryId(),d.componentName(),d.componentValue(),d.componentQuantity(),d.componentLocation(),d.componentNotes());load();}}catch(SQLException ex){LoginFrame.dbError(ex);}}
 private void stock(int delta){int id=selectedId();if(id<0){JOptionPane.showMessageDialog(this,"Select a component first.");return;}try{dao.changeQuantity(user.getId(),id,delta);load();}catch(SQLException ex){LoginFrame.dbError(ex);}}
 private void delete(){int id=selectedId();if(id<0){JOptionPane.showMessageDialog(this,"Select a component first.");return;}if(JOptionPane.showConfirmDialog(this,"Delete selected component?","Confirm",JOptionPane.YES_NO_OPTION)==JOptionPane.YES_OPTION)try{dao.delete(user.getId(),id);load();}catch(SQLException ex){LoginFrame.dbError(ex);}}
 private void addCategory(){String name=JOptionPane.showInputDialog(this,"Category name:");if(name==null||name.trim().isEmpty())return;try{categoriesDao.add(user.getId(),name);JOptionPane.showMessageDialog(this,"Category added.");}catch(SQLException ex){JOptionPane.showMessageDialog(this,"Could not add category (it may already exist).\n"+ex.getMessage());}}
}
